import {captureFeedback,presentFeedback} from './combat-feedback.js?v=1';
import {HEROES,CARDS,MAX_CORE,CORE_REGEN,createRun,continueStage,enterBattle,playCard,endTurn,advance,intent,restore,serialise,availableNodes,chooseNode,selectTarget,RELICS,resolveRoom,buy,sell,usePotion,INVADERS,BEASTS,RARITIES,SHARDS,captureChance,captureBeast,companionReady,useCompanion,equipCompanion,CARD_UPGRADES,upgradeCard,shopUpgradeCard,MYSTERY_EVENTS} from './engine.js?v=72';
import {validBeast,beastKey,addDiscovery,companionDescription,restoreBestiary, beastLevelFromXp, beastBonuses} from './beasts.js?v=15';
import {kaerunLevelFromXp,kaerunBonuses,KAERUN_LEVEL_REWARDS,ilyraLevelFromXp,ilyraBonuses,ILYRA_LEVEL_REWARDS} from './progression.js?v=2';

const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const keys={run:'veyrak.ascension.run.v4',archive:'veyrak.ascension.archive.v1',bestiary:'veyrak.ascension.bestiary.v1',settings:'veyrak.ascension.settings.v1',progression:'veyrak.ascension.progression.v1'};
let storageError=false,feedbackBusy=false;let feedbackVisible=new Set();
function read(k){try{return localStorage.getItem(k);}catch{storageError=true;return null;}}
function write(k,v){try{localStorage.setItem(k,v);return true;}catch{storageError=true;notify('Your browser could not save. Keep this tab open to retain this run.');return false;}}
let run=restore(read(keys.run)),selected='kaerun',screen='title',settings={sound:false,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches},history=[],audio,storyPage=0,storyStage=1;
try{const s=JSON.parse(read(keys.settings));if(s&&typeof s.sound==='boolean'&&typeof s.motion==='boolean')settings=s;}catch{}
try{const a=JSON.parse(read(keys.archive));if(Array.isArray(a))history=a.filter(x=>x&&typeof x.seed==='string'&&HEROES.some(h=>h.id===x.hero)&&['won','lost','abandoned'].includes(x.outcome)&&Number.isInteger(x.turns)).slice(0,30);}catch{}
let bestiary=restoreBestiary(read(keys.bestiary)),bestiaryReturn='title',progression={kaerunXp:0,ilyraXp:0};try{const p=JSON.parse(read(keys.progression));if(p&&Number.isFinite(p.kaerunXp)&&p.kaerunXp>=0)progression.kaerunXp=Math.floor(p.kaerunXp);if(p&&Number.isFinite(p.ilyraXp)&&p.ilyraXp>=0)progression.ilyraXp=Math.floor(p.ilyraXp);}catch{}
const transparentEnemyCache=new Map();
function stripEnemyWhiteBackground(img){
 if(!img?.classList?.contains('stage2-art')||img.dataset.cleaned==='1')return;
 const src=img.getAttribute('src');if(transparentEnemyCache.has(src)){img.dataset.cleaned='1';img.src=transparentEnemyCache.get(src);return;}
 try{const c=document.createElement('canvas'),w=img.naturalWidth,h=img.naturalHeight;if(!w||!h)return;c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0);const d=x.getImageData(0,0,w,h),p=d.data,seen=new Uint8Array(w*h),q=new Int32Array(w*h),push=(i)=>{if(!seen[i]){const k=i*4,r=p[k],g=p[k+1],b=p[k+2];if(r>=232&&g>=232&&b>=232&&Math.max(r,g,b)-Math.min(r,g,b)<=22){seen[i]=1;q[tail++]=i;}}};let head=0,tail=0;for(let xx=0;xx<w;xx++){push(xx);push((h-1)*w+xx);}for(let yy=0;yy<h;yy++){push(yy*w);push(yy*w+w-1);}while(head<tail){const i=q[head++],k=i*4;p[k+3]=0;const xx=i%w,yy=(i/w)|0;if(xx)push(i-1);if(xx<w-1)push(i+1);if(yy)push(i-w);if(yy<h-1)push(i+w);}x.putImageData(d,0,0);let left=w,top=h,right=-1,bottom=-1;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++)if(p[(yy*w+xx)*4+3]>8){left=Math.min(left,xx);right=Math.max(right,xx);top=Math.min(top,yy);bottom=Math.max(bottom,yy);}if(right<left)return;const pad=Math.round(Math.max(right-left,bottom-top)*.04),crop=document.createElement('canvas');crop.width=right-left+1+pad*2;crop.height=bottom-top+1+pad*2;crop.getContext('2d').drawImage(c,left,top,right-left+1,bottom-top+1,pad,pad,right-left+1,bottom-top+1);const clean=crop.toDataURL('image/png');transparentEnemyCache.set(src,clean);img.dataset.cleaned='1';img.src=clean;}catch{}
}
app.addEventListener('load',e=>stripEnemyWhiteBackground(e.target),true);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function icon(kind){const paths={strike:'M7 25 23 9m-1-5 6 6M4 28l6-2-4-4-2 6Z',guard:'M16 3 27 8v9c0 6-11 12-11 12S5 23 5 17V8Z',surge:'m18 2-12 17h9l-1 11 12-18h-9Z',lock:'M9 14V9a7 7 0 0 1 14 0v5M6 14h20v16H6Zm10 6v5',core:'m16 2 12 14-12 14L4 16Z',back:'m20 6-10 10 10 10',pause:'M11 7v18m10-18v18',sound:'M5 13h6l8-7v20l-8-7H5Zm19-3q7 6 0 12'};return `<svg viewBox="0 0 32 32" aria-hidden="true"><path d="${paths[kind]||paths.core}"/></svg>`;}
function button(label,action,cls='gold',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function notify(text){$('#notice').textContent=text;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',6500);}
function sound(low=false){if(!settings.sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(low?165:440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(low?65:660,audio.currentTime+.13);g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.17);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.18);}catch{}}
function hero(){return HEROES.find(h=>h.id===(run?.hero||selected));}
function syncBestiary(){if(!run)return;const before=JSON.stringify(bestiary),caughtBefore=bestiary.caught.length;bestiary.xp??={};const dup=Math.max(0,(run.beastDuplicateXp||0)-(run.beastDuplicateXpBanked||0));if(dup&&run.captureResult?.caught&&run.captureResult?.duplicate){bestiary.xp[run.captureResult.id]=(bestiary.xp[run.captureResult.id]||0)+dup;run.beastDuplicateXpBanked=(run.beastDuplicateXpBanked||0)+dup;}for(const x of run.seenBeasts||[])addDiscovery(bestiary.seen,x);for(const x of run.capturedBeasts||[]){addDiscovery(bestiary.caught,x);addDiscovery(bestiary.seen,x);}if(!bestiary.selected&&caughtBefore===0&&bestiary.caught.length>0)bestiary.selected={...run.capturedBeasts[0]};if(before!==JSON.stringify(bestiary))write(keys.bestiary,JSON.stringify(bestiary));}
function syncBeastProgression(){if(!run||!run.companion)return;const earned=Math.max(0,(run.beastXpEarned||0)-(run.beastXpBanked||0));if(!earned)return;bestiary.xp??={};bestiary.xp[run.companion.id]=(bestiary.xp[run.companion.id]||0)+earned;run.beastXpBanked=(run.beastXpBanked||0)+earned;write(keys.bestiary,JSON.stringify(bestiary));}
function syncProgression(){if(!run||!['kaerun','ilyra'].includes(run.hero))return;const earned=Math.max(0,(run.characterXpEarned||0)-(run.characterXpBanked||0));if(!earned)return;progression[run.hero+'Xp']=(progression[run.hero+'Xp']||0)+earned;run.characterXpBanked=(run.characterXpBanked||0)+earned;write(keys.progression,JSON.stringify(progression));}
function save(){if(run){syncBestiary();syncBeastProgression();syncProgression();write(keys.run,serialise(run));}}
function record(outcome){if(!run||run.recorded)return;history.unshift({seed:run.seed,hero:run.hero,outcome,turns:run.turns,cards:run.cardsPlayed});history=history.slice(0,30);write(keys.archive,JSON.stringify(history));run.recorded=true;save();}
function persistAction(fn,...args){if(!fn(run,...args))return false;if(run.phase==='won'||run.phase==='lost')record(run.phase);save();return true;}
async function performCombatAction(action,...args){
 if(feedbackBusy||run?.phase!=='combat')return false;
 const before={hp:run.hp,block:run.block,enemies:run.battle.enemies.map(e=>({...e}))};
 const result=captureFeedback(run,()=>persistAction(action,...args));if(!result.ok)return false;
 const events=result.events,b=run.battle;
 if(run.block>before.block&&action!==endTurn)events.push({kind:'guard',target:'player',text:'+'+(run.block-before.block)+' Block',offset:30});
 if(run.hp>before.hp)events.push({kind:'heal',target:'player',text:'+'+(run.hp-before.hp)+' Vitality',offset:-25});
 b.enemies.forEach((e,i)=>{
  const old=before.enemies[i];if(!old)return;
  for(const [key,label]of [['mark','Mark'],['weak','Weak'],['vulnerable','Vulnerable']])if((e[key]||0)>(old[key]||0))events.push({kind:'status',target:'enemy:'+i,text:label+' +'+(e[key]-(old[key]||0)),offset:-45});
  if(e.phase===2&&old.phase!==2)events.push({kind:'status',target:'enemy:'+i,text:'ENRAGED',offset:-65});
  if(action===endTurn){const accounted=events.filter(x=>x.kind==='hit'&&x.target==='enemy:'+i).reduce((n,x)=>n+x.damage,0),remaining=old.hp-e.hp-accounted;if(remaining>0)events.push({kind:'hit',source:'enemy:'+i,target:'enemy:'+i,damage:remaining,blocked:0});}
 });
 if(!events.length){navigate(run.phase);return true;}
 feedbackBusy=true;feedbackVisible=new Set(before.enemies.flatMap((e,i)=>e.hp>0?[i]:[]));screen='combat';render();
 try{sound(action===endTurn);await presentFeedback(events,{motion:settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches,hero:run.hero});}
 finally{feedbackBusy=false;feedbackVisible.clear();navigate(run.phase);}
 return true;
}
function title(){return `<main class="title screen"><div class="title-shade"></div><div class="title-content"><img class="title-logo" src="assets/6FBB8F62-9010-4EC2-8342-E73B43951CB7.png" alt="Veyrak: Ascension"><div class="title-rule"></div><nav aria-label="Main menu">${run&&!['won','lost'].includes(run.phase)?button('Continue ascent','continue'):''}${button('Begin ascent','select')}${button('Bestiary','bestiary')}${button('Archive','archive')}${button('Settings','settings')}</nav></div><footer><span>VEYATHUUN AWAITS</span><span>BEASTBOUND · v0.18</span></footer></main>`;}
const storyPages={
 1:[
  {src:'assets/story/DDF46E97-E6E6-4984-9189-6B1C21BD73B6.png',alt:'Veyathuun before the impact, the anomaly is discovered and the Council responds.'},
  {src:'assets/story/59C50C17-A4FE-4F12-B467-E1C06750E9FC.png',alt:'The meteor strikes Veyathuun and Kaerun and Ilyra enter the ruined district.'},
  {src:'assets/story/1B2E0ED6-7F91-4355-BB01-72EB0A4368F5.png',alt:'Alien beasts emerge beneath Veyathuun as Kaerun and Ilyra begin their ascent.'}
 ],
 2:[
  {src:'assets/story/18D98338-4014-48B0-BA0A-D718433CE20E.png',alt:'Kaerun and Ilyra discover the entrance to the Shattered Depths beneath the impact site.'},
  {src:'assets/story/05C7A73A-A98A-489F-A14E-7321C41811E7.png',alt:'The Veyrakians explore an enormous deliberate network of subterranean tunnels.'},
  {src:'assets/story/D6D1AFF7-F768-40D5-B9B2-DAED3F19A42E.png',alt:'A Veyrakian control room maps the tunnels and reveals that they converge on the planetary core.'}
 ]
};
function story(){const pages=storyPages[storyStage]||storyPages[1],p=pages[storyPage];return `<main class="story comic-story screen"><img class="story-comic-page" src="${p.src}" alt="${p.alt}"><div class="comic-story-controls">${storyPage?button('Previous','story-previous','quiet'):''}${button(storyPage===pages.length-1?(storyStage===1?'Begin ascent':'Enter Stage 2'):'Next page','story-next')}${button('Skip story','story-skip','quiet')}</div></main>`;}
function select(){const h=HEROES.find(x=>x.id===selected),kp=h.id==='ilyra'?ilyraLevelFromXp(progression.ilyraXp):kaerunLevelFromXp(progression.kaerunXp),level=['kaerun','ilyra'].includes(h.id)?kp.level:1;return `<main class="selection screen"><header class="topbar">${button(icon('back')+'<span>Back</span>','title','quiet')}<h1>Choose your Veyrakian</h1><span class="eyebrow council-label">Veyathuun Council</span></header><div class="select-stage"><div class="hero-progression-wrap"><button class="progression-hint progression-open" data-action="progression" aria-label="View ${h.name} progression">Tap for progression</button><button class="hero-display hero-progression-trigger" data-action="progression" aria-label="View ${h.name} progression"><img class="hero-art" src="assets/${h.id}.png" alt="${h.name}" fetchpriority="high"></button></div><section class="dossier"><div class="dossier-mark">${icon('core')}</div><p class="eyebrow">Council dossier</p><h2>${h.name}</h2><p class="subtitle">${h.title}</p>${['kaerun','ilyra'].includes(h.id)?`<div class="level-readout"><strong class="character-level">LEVEL ${kp.level}</strong><span class="character-xp">${kp.level>=20?'MAX LEVEL':`${kp.intoLevel} / ${kp.next} XP`}</span><small class="character-perk">${h.id==='ilyra'?ILYRA_LEVEL_REWARDS[kp.level]:KAERUN_LEVEL_REWARDS[kp.level]}</small></div>`:''}<div class="gold-rule"></div><div class="traits"><div>${icon(h.id==='kaerun'?'strike':'surge')}<span>${h.weapon}</span></div><div>${icon('guard')}<span>${h.id==='kaerun'?80+kaerunBonuses(kp.level).maxHp:h.id==='ilyra'?80+ilyraBonuses(kp.level).maxHp:80} Vitality</span></div></div><label class="seed-label" for="seed">Run seed <span>Optional</span></label><input id="seed" maxlength="32" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Leave blank for a new ascent"><p class="seed-help">Same seed. Same encounters.</p>${button('Begin ascent','start')}<p class="starter-note">10 starter cards · 5 Basic Shards · Stage 1: 10 levels + boss</p><p class="hero-playstyle">${h.id==='ilyra'?'Build violet Resonance; spend it on attacks or lasting protection.':'Mark enemies with your gauntlets. Your first attack on a Marked foe each turn grants 3 Block.'}</p>${button(bestiary.selected?`Companion: ${BEASTS[bestiary.selected.id].name}`:'Choose companion','bestiary','quiet companion-select')}</section></div><nav class="hero-roster" aria-label="Choose hero">${HEROES.map(h=>`<button class="hero-choice ${selected===h.id?'selected':''} ${!h.available?'locked':''}" data-action="hero" data-hero="${h.id}" ${h.available?`aria-pressed="${selected===h.id}"`:'aria-disabled="true"'} aria-label="${h.name}${h.available?'':', locked'}"><span class="portrait" style="--portrait-x:${h.portrait}%"></span><span class="hero-name">${h.name}${!h.available?'<small>Locked</small>':''}</span></button>`).join('')}</nav></main>`;}

function progressionDialog(){const h=HEROES.find(x=>x.id===selected);if(!['kaerun','ilyra'].includes(h.id)){notify('Character progression for '+h.name+' will be added with their level system.');return;}const isI=h.id==='ilyra',p=isI?ilyraLevelFromXp(progression.ilyraXp):kaerunLevelFromXp(progression.kaerunXp),b=isI?ilyraBonuses(p.level):kaerunBonuses(p.level),rewards=isI?ILYRA_LEVEL_REWARDS:KAERUN_LEVEL_REWARDS,pct=p.level>=20?100:Math.round(p.intoLevel/p.next*100);const active=isI?['Max Vitality: '+(80+b.maxHp),'Resonance cap: '+b.resonanceCap,'Starting Resonance: '+b.startingResonance,'Starting Core bonus: +'+b.startingCore,'Starting Barrier: '+b.startingBarrier]:['Max Vitality: '+(80+b.maxHp),'Starting Core bonus: +'+b.startingCore,'Opening draw bonus: +'+b.firstTurnDraw,'Block each turn: '+b.turnBlock];const levels=rewards.slice(1).map((reward,i)=>{const level=i+1,state=level<p.level?'unlocked':level===p.level?'current':'locked';return '<article class="mastery-level '+state+(level%5===0?' milestone':'')+'"><b>'+level+'</b><div><strong>Level '+level+'</strong><p>'+reward+'</p></div><span>'+(state==='unlocked'?'DONE':state==='current'?'CURRENT':'LOCKED')+'</span></article>';}).join('');const play=isI?'<strong>Resonance tactician.</strong> Build Resonance with crystal techniques, then choose the right moment to spend it on powerful attacks, Barrier or healing. Her progression expands how much Resonance she can hold and rewards careful spend timing.':'<strong>Armoured pressure fighter.</strong> Apply Mark with Kaerun’s gauntlets, then attack Marked enemies to generate Block while maintaining offensive pressure. His permanent progression increasingly rewards Mark management and turn-by-turn defence.';openModal(h.name+' Mastery','<section class="mastery"><div class="mastery-playstyle"><span>PLAYSTYLE</span><p>'+play+'</p></div><h3>Level '+p.level+'</h3><strong>'+p.totalXp+' total XP</strong><div class="xp-track"><i style="width:'+pct+'%"></i></div><small>'+(p.level>=20?'Maximum mastery reached':p.intoLevel+' / '+p.next+' XP to Level '+(p.level+1))+'</small><div class="mastery-bonuses">'+active.map(x=>'<span>'+x+'</span>').join('')+'</div><div class="mastery-levels">'+levels+'</div></section>');}
function runHeader(label){return `<header class="topbar run-top"><div class="run-brand">Veyrak <span>Ascension</span></div><div class="run-location">${label}<small>STAGE ${run.stage||1} / 10 · SEED ${escape(run.seed)}</small></div>${button(icon('pause')+'<span>Menu</span>','pause','quiet')}</header>`;}
const nodeNames={beast:'Beast',battle:'Battle',elite:'Elite',boss:'Boss',shop:'Shop',chest:'Treasure',mystery:'Mystery',rest:'Sanctuary'};

const ITEM_ASSETS={potion:'healing-potion.png',basic:'basic-shard.png',refined:'refined-shard.png',prismatic:'prismatic-shard.png',chest:'treasure-chest.png',gold:'gold-coin.png'};
function itemArt(id,size='inline'){return '<img class="item-art item-'+size+'" src="assets/items/'+ITEM_ASSETS[id]+'" width="28" height="28" alt="" aria-hidden="true" draggable="false">';}

const nodeIcons={beast:itemArt('basic','map'),battle:'⚔',elite:'◆',boss:'♛',shop:itemArt('gold','map'),chest:itemArt('chest','map'),mystery:'?',rest:'✦'};

function inventoryBar(){return `<div class="inventory-bar"><span>♥ ${run.hp}/${run.maxHp}</span><span class="item-count">${itemArt('gold')} ${run.gold} gold</span>${button(`Deck · ${run.deck.length}`,'cards','quiet')}${button(`Relics · ${run.relics.length}`,'relics','quiet')}${button(run.companion?BEASTS[run.companion.id].name:'Companion','bestiary','quiet')}<span class="shard-counts" aria-label="Capture shards"><span class="item-count" title="Basic Shards">${itemArt('basic')} <span aria-label="basic shards">${run.shards.basic}</span></span><span class="item-count" title="Refined Shards">${itemArt('refined')} <span aria-label="refined shards">${run.shards.refined}</span></span><span class="item-count" title="Prismatic Shards">${itemArt('prismatic')} <span aria-label="prismatic shards">${run.shards.prismatic}</span></span></span>${button(`${itemArt('potion')}Potion · ${run.potions}`,'potion','quiet',run.potions&&run.hp<run.maxHp?'':'disabled')}${run.blessing?`<span>+${run.blessing} Strength</span>`:''}${run.curse?`<span>Core drain: ${run.curse} turns</span>`:''}</div>`;}
function map(){const available=run?.debugUnlockAll?run.route.filter(n=>!run.visited.includes(n.id)).map(n=>n.id):availableNodes(run);const pos=n=>({x:60+n.row*110,y:n.type==='boss'?130:45+n.col*85});return `<main class="route screen">${runHeader('Choose your path')}<section class="branch-panel"><div class="map-heading"><h1>The gates of Veyathuun</h1><p>Stage 1 has ten levels, then the Gate Warden. Swipe to explore the route.</p></div>${inventoryBar()}<div class="branch-scroll"><div class="branch-map"><svg viewBox="0 0 1220 270" preserveAspectRatio="none" aria-hidden="true">${run.route.flatMap(n=>n.next.map(id=>{const v=run.route.find(x=>x.id===id),a=pos(n),b=pos(v);return `<path class="${run.visited.includes(n.id)&&run.visited.includes(id)?'travelled':run.current===n.id?'open-path':''}" d="M${a.x} ${a.y} L${b.x} ${b.y}"/>`;})).join('')}</svg>${run.route.map(n=>{const p=pos(n),visited=run.visited.includes(n.id),secret=!visited&&n.type==='battle',name=secret?'Encounter':nodeNames[n.type],symbol=visited?'✓':secret?'◈':nodeIcons[n.type],beastClass=n.type==='beast'?'beast-node'+(visited?' rarity-'+n.enemy.rarity:''):'',detail=secret||n.type==='beast'&&!visited?'':n.type==='beast'?`<small>${RARITIES[n.enemy.rarity].name}<br>${BEASTS[n.enemy.beast].role}</small>`:n.type==='battle'&&n.enemy.size?`<small>${n.pack?'Pair of invaders':'Large invader'}</small>`:'';return `<button class="branch-node ${beastClass} ${available.includes(n.id)?'available':''} ${visited?'visited':''}" style="left:${p.x/12.2}%;top:${p.y/2.7}%" data-action="node" data-id="${n.id}" ${available.includes(n.id)?'':'disabled'} aria-label="Level ${n.row+1}: ${name}"><b>${symbol}</b><span>${name}</span>${detail}</button>`;}).join('')}</div></div><p class="map-legend">◈ Encounter · ✧ Beast · ▣ Relic & supplies · ? Risk & reward · ¤ Buy / sell · ✦ Heal</p></section></main>`;}
const NEUTRAL_CARD_ASSETS={
 meteor:'meteor_fragment.png',
