const TECH_PATHS={
 mark:'M50 18v19m0 26v19M18 50h19m26 0h19M50 30a20 20 0 1 0 0 40 20 20 0 0 0 0-40Zm0 15a5 5 0 1 0 0 10 5 5 0 0 0 0-10Z',
 core:'M50 14 75 50 50 86 25 50 50 14Zm0 13v46M32 50h36',
