function cardArt(id,cls=''){
 const c=CARDS[id];
 if(c.upgradeOf){const base=cardArt(c.upgradeOf);return `<span class="upgraded-card-art ${cls}" role="img" aria-label="${escape(c.name)}, ${c.cost} Core. ${escape(c.text)}"><span class="upgrade-base" aria-hidden="true">${base}</span><span class="upgrade-card-cost" aria-hidden="true">${c.cost}</span><strong class="upgrade-card-name" aria-hidden="true">${escape(c.name)}</strong><span class="upgrade-card-effect" aria-hidden="true">${escape(c.text)}</span><span class="upgrade-plus" aria-hidden="true">+</span></span>`;}
 const t=c.tile;
 const finished=FINISHED_CARD_ASSETS[id];
 if(finished)return `<img class="neutral-card neutral-card-png finished-card card-${id} ${cls}" src="assets/card-masks/${finished}" alt="${c.name}" draggable="false">`;
 if(c.modernArt)return `<span class="tech-card tech-${c.ilyra?'ilyra':c.kaerun?'kaerun':'shared'} tech-${c.type} ${cls}" role="img" aria-label="${c.name}, ${c.cost} Core. ${c.text}"><b class="tech-cost">${c.cost}</b><strong class="tech-name">${c.name}</strong><span class="tech-scene" aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="37"/><path d="${TECH_PATHS[c.modernArt]}"/></svg></span><em class="tech-kind">${c.type}</em><span class="tech-effect">${c.text}</span></span>`;
 if(c.ilyra)return `<span class="ilyra-card ${cls}" role="img" aria-label="${c.name}, ${c.cost} Core. ${c.text}"><img src="assets/ilyra-cards/${id}.webp" alt="" draggable="false"><b class="ilyra-cost">${c.cost}</b><strong class="ilyra-name">${c.name}</strong><em class="ilyra-type">${c.type}</em><span class="ilyra-effect">${c.text}</span></span>`;
 if(t===undefined){
  const asset=NEUTRAL_CARD_ASSETS[id];
  return `<img class="neutral-card neutral-card-png card-${id} ${cls}" src="assets/card-masks/${asset}" alt="${c.name}" draggable="false">`;
 }
 return `<span class="sheet-card tile-${t} ${cls}" style="--cx:${t%5};--cy:${Math.floor(t/5)}" role="img" aria-label="${c.name}"></span>`;
}
const RELIC_ASSETS={amber:'amber_heart.png',aegis:'ivory_aegis.png',fist:'sovereign_seal.png',emberstone:'emberstone.png',wayfarer:'wayfarers_compass.png',coreprism:'core_prism.png',thorncrown:'crown_of_thorns.png',gilded:'gilded_scarab.png',moonchalice:'moon_chalice.png',wardstone:'wardstone.png',hunterlens:'hunters_lens.png',hourglass:'dusk_hourglass.png'};
function relicArt(id){const r=RELICS[id],asset=RELIC_ASSETS[id];return asset?`<img class="relic-art" src="assets/${asset}" alt="${r.name}" draggable="false">`:'<b class="relic-fallback">◆</b>';}
function relicEntry(id){return `<article class="relic-entry">${relicArt(id)}<div><strong>${RELICS[id].name}</strong><p>${RELICS[id].text}</p></div></article>`;}
function cardOffer(id,action,extra=''){const c=CARDS[id];return `<button class="offer-card" data-action="${action}" data-id="${id}" ${extra}>${cardArt(id)}<strong>${c.name}</strong><span>${c.cost} Core · ${c.text}</span></button>`;}

function mysteryContent(){
 const t=run.room,title=MYSTERY_EVENTS[t.eventId],heading=(run.stage===2?title.cavern:title.name);
 const choose=(label,choice,disabled=false)=>button(label,'room','gold','data-choice="'+choice+'" '+(disabled?'disabled':''));
 const leave=button('Leave untouched','room','quiet','data-choice="leave"');
 if(t.result)return '<h1>'+heading+'</h1><p>'+escape(t.result)+'</p>'+choose('Continue journey','leave');
 let body='';
 if(t.step==='upgrade')body='<p>Trial reward: upgrade one card for free.</p><div class="upgrade-list">'+upgradeChoices().map(x=>'<article class="event-technique"><strong>'+escape(CARDS[x.id].name)+' → '+escape(CARDS[CARD_UPGRADES[x.id]].name)+'</strong><p>'+escape(CARDS[CARD_UPGRADES[x.id]].text)+'</p>'+choose('Upgrade this card','upgrade:'+x.index)+'</article>').join('')+'</div>';
 else switch(t.eventId){
 case 'forge':
  body='<p>Upgrade one card for 50 gold or 10 Vitality. Choose your card and payment below.</p><div class="upgrade-list">'+upgradeChoices().map(x=>'<article class="event-technique"><strong>'+escape(CARDS[x.id].name)+' → '+escape(CARDS[CARD_UPGRADES[x.id]].name)+'</strong><p>'+escape(CARDS[CARD_UPGRADES[x.id]].text)+'</p><div class="dialog-actions">'+choose('Pay 50 gold','forge:'+x.index+':gold',run.gold<50)+choose('Spend 10 Vitality','forge:'+x.index+':health',run.hp<=10)+'</div></article>').join('')+'</div>';
  if(!upgradeChoices().length)body+='<p>All your cards are already upgraded.</p>';break;
 case 'exchange':
  body='<p>Trade one card for one of the three replacements below. Your deck stays the same size.</p><div class="offers">'+t.cards.map(id=>'<article class="collection-card">'+cardArt(id)+'<strong>'+escape(CARDS[id].name)+'</strong><p>'+escape(CARDS[id].text)+'</p></article>').join('')+'</div><p>Select the card you want to trade, then confirm a replacement.</p><div class="sell-list">'+run.deck.map((id,i)=>button('Trade '+escape(CARDS[id].name),'event-exchange','quiet','data-index="'+i+'"')).join('')+'</div>';break;
 case 'crystal':
  body='<p>Collect 40 gold safely, or fracture the crystal: 70% chance of a relic; 30% chance of losing up to 12 Vitality. The fracture will leave at least 1 Vitality.</p><div class="dialog-actions">'+choose(itemArt('gold')+'Take 40 gold','safe')+choose('Fracture · 70% relic / 30% injury','risk')+'</div>';break;
 case 'explorer':
  body='<p>Give one healing potion for your choice of a rare technique below, or pay 25 gold for a random technique.</p><div class="offers">'+t.rare.map(id=>cardOffer(id,'room','data-choice="potion:'+id+'" '+(run.potions<1?'disabled':''))).join('')+'</div>'+choose('Pay 25 gold · Random card','gold',run.gold<25);break;
 case 'armoury':
  body='<p>Force the door for 12 Vitality and take one upgraded card. Payment is made only when you choose a card.</p><div class="offers">'+t.cards.map(id=>cardOffer(CARD_UPGRADES[id],'room','data-choice="armoury:'+id+'" '+(run.hp<=12?'disabled':''))).join('')+'</div>';break;
 case 'remains':
  body='<p>Choose one supply to carry onwards.</p><div class="dialog-actions">'+choose(itemArt('basic')+'3 Basic Shards','basic')+choose(itemArt('refined')+'1 Refined Shard','refined')+choose(itemArt('gold')+'20 gold','gold')+'</div>';break;
 case 'whisper':
  body='<p>Take this relic. Start your next two battles with 1 less Core on their first turn.</p>'+(t.relic?relicEntry(t.relic)+choose('Accept relic · Two-battle Core penalty','accept',run.relics.includes(t.relic)):'<p>You already own every relic.</p>');break;
 case 'trial':{
  const e=t.trialEnemy;
  body=e?'<p>Challenge this elite for 85 gold, an unowned relic if available, a card reward and a guaranteed free upgrade after victory. Your relic bonuses still apply.</p><article class="event-technique"><h2>'+escape(e.name)+'</h2><p>'+e.hp+' Vitality</p><p>'+e.moves.map(m=>escape(m.name||m.kind)+' · '+m.value+(m.hits?' × '+m.hits:'')).join(' / ')+'</p></article>'+choose('Fight the elite','fight'):'<p>The trial is silent.</p>';break;
 }
 }
 return '<h1>'+heading+'</h1>'+body+leave;
}

function room(){const kind=run.phase;let content='';if(kind==='chest'){const t=run.room;content=t.revealed?`<div class="treasure-result ${t.bad?'cursed':'fortunate'}"><p class="eyebrow">${t.bad?'Cursed treasure':'Treasure discovered'}</p><h1>${t.bad?'The vault strikes back':'Fortune favours you'}</h1><p>${escape(t.result)}</p>${!t.bad&&t.relic?relicEntry(t.relic):''}${button('Continue journey','room','gold','data-choice="leave"')}</div>`:`<div class="treasure-result"><p class="eyebrow">A sealed vault</p><h1>The forgotten vault</h1>${itemArt('chest','chest')}<p>80% chance of a relic, gold and a potion.<br>20% chance of a trap, gold loss or temporary Core drain.</p>${button('Open the chest','room','gold','data-choice="open"')}</div>`;}
if(kind==='rest'){const eligible=run.deck.map((id,i)=>({id,i,next:CARD_UPGRADES[id]})).filter(x=>x.next);content=`<h1>Sanctuary</h1><p>Recover before continuing, or strengthen one technique for the rest of this ascent.</p><div class="sanctuary-actions">${button('Rest · +24 Vitality','room','gold','data-choice="rest"')}${eligible.length?button('Upgrade a card','upgrade-list','quiet'):`<button class="quiet" disabled>All eligible cards upgraded</button>`}</div><p class="small muted">Upgraded cards gain a gold + frame and improved effects. Each card can be upgraded once at a Sanctuary.</p>`;}
if(kind==='mystery'&&run.room.eventVersion===1){content=mysteryContent();}
if(kind==='mystery'&&run.room.eventVersion!==1){const k=run.room.kind;content=k==='cache'?`<h1>A warrior’s legacy</h1><p>Choose one abandoned technique for your deck.</p><div class="offers">${run.room.cards.map(id=>cardOffer(id,'room',`data-choice="${id}"`)).join('')}</div>`:k==='shrine'?`<h1>The amber shrine</h1><p>Offer 8 Vitality. Gain +1 Strength every turn for this run.</p>${button('Make the offering','room','gold',`data-choice="accept" ${run.hp<=8?'disabled':''}`)}`:`<h1>A whisper in the rift</h1><p>Gain ${CARDS[run.room.cards[0]].name} and 45 gold, but start your next two turns with only 2 Core.</p>${button('Accept the bargain','room','gold','data-choice="accept"')}`;content+=button('Leave untouched','room','quiet','data-choice="leave"');}
if(kind==='shop'){const upgradeable=run.deck.map((id,i)=>({id,i,next:CARD_UPGRADES[id]})).filter(x=>x.next);content=`<h1>The wandering merchant</h1><p>Buy techniques and supplies. Sell spare cards for 10 gold (keep at least 5).</p><div class="merchant-forge"><strong>Technique Forge</strong><span>Upgrade one eligible card · 75 gold</span>${upgradeable.length?button('Forge a card · 75','shop-upgrade-list','gold',`${run.gold<75?'disabled':''}`):'<button class="quiet" disabled>No eligible cards</button>'}</div><div class="shop-stock">${run.room.stock.map((x,i)=>`<article>${x.kind==='card'?cardArt(x.id):x.kind==='potion'?itemArt('potion','shop'):x.kind==='shard'?itemArt(x.id,'shop'):relicArt(x.id)}<strong>${x.kind==='card'?CARDS[x.id].name:x.kind==='potion'?'Healing potion':x.kind==='shard'?`${x.quantity} × ${SHARDS[x.id].name}`:RELICS[x.id].name}</strong><p>${x.kind==='card'?CARDS[x.id].text:x.kind==='potion'?`Restore ${run.relics.includes('moonchalice')?28:20} Vitality.`:x.kind==='shard'?SHARDS[x.id].description:RELICS[x.id].text}</p>${button(x.sold?'Sold':`Buy · ${x.price} gold`,'buy','quiet',`data-index="${i}" ${x.sold||run.gold<x.price?'disabled':''}`)}</article>`).join('')}</div><div class="sell-list">${run.deck.map((id,i)=>button(`Sell ${CARDS[id].name} · 10`,'sell','quiet',`data-index="${i}" data-kind="card" ${run.deck.length<=5?'disabled':''}`)).join('')}${button('Sell potion · 12','sell','quiet',`data-kind="potion" ${run.potions?'':'disabled'}`)}</div>${button('Continue journey','room','gold','data-choice="leave"')}`;}
return `<main class="route screen room-screen">${runHeader(nodeNames[kind])}<section class="room-panel">${inventoryBar()}${content}</section></main>`;}
function enemyArt(e){if(e.boss)return `<img class="enemy-art boss boss-art" src="assets/invaders/${e.art||'614E751C-C1E9-4B14-B7C6-A397BB995A97.png'}" alt="${e.name}" draggable="false">`;if(e.stage2&&e.art)return `<img class="enemy-art invader-art stage2-art ${e.elite?'elite-invader':''} invader-${e.size}" src="assets/invaders/${e.art}" alt="${e.name}" draggable="false" data-cleaned="1">`;if(INVADERS.some(x=>x.id===e.id))return `<img class=\"enemy-art invader-art ${e.elite?'elite-invader':''} invader-${e.size}\" src=\"assets/invaders/${e.id}.webp\" alt=\"${e.name}\" draggable=\"false\">`;if(e.beast)return `<img class="enemy-art beast-art rarity-${e.rarity}" src="assets/beasts/${e.beast}.webp" alt="${RARITIES[e.rarity].name} ${e.name}" draggable="false">`;return `<svg class="enemy-art ${e.boss?'boss':''}" viewBox="0 0 280 340" role="img" aria-label="${e.name}, a floating crystalline guardian" style="--enemy:${e.colour}"><defs><linearGradient id="crystal" x2="1" y2="1"><stop stop-color="${e.colour}"/><stop offset=".48" stop-color="#283440"/><stop offset="1" stop-color="#0a111d"/></linearGradient></defs><ellipse cx="140" cy="311" rx="65" ry="12" fill="#000" opacity=".3"/><g class="crystal-body"><circle cx="140" cy="165" r="100" fill="none" stroke="${e.colour}" opacity=".2"/><path d="m140 28 73 84-21 103-52 71-52-71-21-103Z" fill="url(#crystal)" stroke="${e.colour}" stroke-width="2"/><path d="m140 28-22 103 22 155 24-155Zm-73 84 73 53 73-53M88 215l52-50 52 50" fill="none" stroke="${e.colour}" opacity=".8"/><path d="m140 114 27 48-27 41-27-41Z" fill="${e.colour}"/><path d="m43 93 20 37-14 64-24-34Zm194 0-20 37 14 64 24-34Z" fill="url(#crystal)" stroke="${e.colour}"/><path d="m94 64 46-48 46 48M85 269l55 34 55-34" fill="none" stroke="#ddbd7b" stroke-width="3"/><circle cx="140" cy="161" r="10" fill="#fff5d7"/></g></svg>`;}
function health(value,max,label){return `<div class="health"><div class="health-label"><span>${label}</span><strong>${value} <small>/ ${max}</small></strong></div><div class="health-track" role="meter" aria-label="${label} health" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${value}"><span style="width:${value/max*100}%"></span></div></div>`;}
function statusBadges(x,player=false){const items=[];if(x.mark)items.push(['Mark',x.mark]);if(x.weak)items.push(['Weak',x.weak]);if(x.vulnerable)items.push(['Vulnerable',x.vulnerable]);if(x.bleed)items.push(['Bleed',x.bleed]);if(x.strength)items.push(['Strength','+'+x.strength]);if(x.barrier)items.push(['Barrier',x.barrier]);if(x.stunned)items.push(['Stun','']);if(x.id==='kharvex_prime'&&x.phase===2)items.push(['Enraged','']);return items.length?`<div class="status-row">${items.map(([n,v])=>`<span class="status status-${n.toLowerCase()}">${n}${v!==''?` ${v}`:''}</span>`).join('')}</div>`:'';}
function combat(){const b=run.battle;return `<main class="battle screen stage-${run.stage||1} ${feedbackBusy?'combat-resolving':''}" aria-busy="${feedbackBusy}">${runHeader(`Level ${run.index+1} / 11 · ${itemArt('gold')} ${run.gold}`)}<section class="arena"><div class="fighter player"><div class="fighter-info">${health(run.hp,run.maxHp,hero().name)}<span class="block">${icon('guard')} ${run.block} Block ${b.strength?`· +${b.strength} Strength`:''}${b.echo?' · Echo ready':''}${b.companionBoost?' · Resonance +'+b.companionBoost+'%':''}</span>${run.hero==='ilyra'?`<span class="resonance-meter" title="Build up to 3 Resonance; spend it on Resonant Strike or Prism Ward">Resonance <b>${'●'.repeat(b.resonance||0)}${'○'.repeat(3-(b.resonance||0))}</b></span>`:`<span class="pressure-meter ${b.pressureUsed?'spent':''}" title="First attack on a Marked enemy each turn grants 3 Block">Gauntlet Pressure <b>${b.pressureUsed?'Spent':'Ready'}</b></span>`}${statusBadges({...b,strength:b.strength,barrier:b.barrier},true)}${b.coreDebt||b.drawPenalty?`<span class="turn-debt">Next turn: ${b.coreDebt?`−${b.coreDebt} Core `:''}${b.drawPenalty?`−${b.drawPenalty} draw`:''}</span>`:''}</div><img class="combat-hero" src="assets/${run.hero}.png" alt="${hero().name}">${run.companion?`<img class="companion-art rarity-${run.companion.rarity}" src="assets/beasts/${run.companion.id}.webp" alt="Companion ${BEASTS[run.companion.id].name}" draggable="false">`:''}</div><div class="turn-medallion"><span>TURN</span><strong>${b.turn}</strong></div><div class="enemy-group">${b.enemies.map((e,i)=>{if(!e.hp&&!feedbackVisible.has(i))return '';const m=intent(run,i);return `<button class="enemy-target ${e.elite?'elite-target':''} ${i===b.target?'targeted':''}" data-action="target" data-index="${i}" aria-label="Target ${e.name}" aria-pressed="${i===b.target}"><div class="fighter-info">${health(e.hp,e.maxHp,e.name)}${e.elite?'<span class=\"elite-badge\">Elite invader</span>':''}${e.beast?`<span class="rarity-badge rarity-${e.rarity}">${RARITIES[e.rarity].name} · ${BEASTS[e.beast].role}</span>`:''}<span class="intent">${m.kind==='recover'?'Exposed — recovering':m.kind==='stun'?'Stunned — skips action':m.kind==='attack'?`Attacks for ${m.value}${m.hits>1?` × ${m.hits}`:''}`:m.kind==='siphon'?`Siphons ${m.value} · heals 3 if it hits`:m.kind==='weaken'?`Applies ${m.value} Weak`:m.kind==='guard'?`Gains ${m.value} Block`:m.kind==='heal'?`Heals ${m.value} Vitality`:m.kind==='empower'?e.id==='duskcaller'?`Empowers pack +${m.value} Strength`:`Gains ${m.value} Strength`:'Gathering power'}</span><small>${e.block?`${e.block} Block · `:''}${i===b.target?'Targeted':''}</small>${statusBadges(e)}</div>${enemyArt(e)}</button>`;}).join('')}</div></section><section class="combat-controls"><div class="combat-toolbar"><div class="core-count" title="+${CORE_REGEN} each turn · unused Core carries over"><span class="core-pips" aria-hidden="true">${Array.from({length:MAX_CORE},(_,i)=>`<i class="${i<run.core?'filled':''}"></i>`).join('')}</span>${icon('core')}<strong>${run.core}<small> / ${MAX_CORE}</small></strong><span>CORE</span></div>${battleActions()}${button('End turn','end','gold end-turn')}</div><div class="hand ${b.hand.length>5?'long-hand':''}" style="--hand-count:${b.hand.length}" aria-label="Your hand">${b.hand.map((id,i)=>`<button class="ability-card ${CARDS[id].cost>run.core?'unaffordable':''}" style="--fan:${i-(b.hand.length-1)/2}" data-action="inspect" data-index="${i}" aria-label="Inspect ${CARDS[id].name}">${cardArt(id)}</button>`).join('')}${b.hand.length?'':'<p class="empty-hand">End your turn to draw again.</p>'}</div><div class="pile-row">${button(`Draw · ${b.draw.length}`,'draw','text-button')}${button(`${itemArt('potion')}Potion · ${run.potions}`,'potion','text-button')}${button(`Discard · ${b.discard.length}`,'discard','text-button')}</div></section></main>`;}
function outcome(){const won=run.phase==='won',lost=run.phase==='lost',stageComplete=run.phase==='stage-complete',elite=!!run.eliteReward;return `<main class="result screen">${runHeader(`Stage ${run.stage||1}`)}<section class="result-panel"><div class="result-symbol">${icon(lost?'guard':'core')}</div><p class="eyebrow">${lost?'The ascent ends':won?'The summit is yours':stageComplete?`Stage ${run.stage} complete`:elite?'Elite defeated':'Path cleared'}</p><h1>${lost?'Rise again.':won?'Ascension':stageComplete?'Stage Complete':elite?'Elite Victory':'Victory'}</h1><p>${lost?'Veyathuun will remember your resolve.':won?'You have conquered all ten stages.':stageComplete?`The Gate Warden has fallen. Your ascent continues into Stage ${run.stage+1}.`:`The encounter is complete. Choose a card to add to your deck.`}</p><div class="result-stats"><div><strong>${run.hp}</strong><span>Vitality remaining</span></div><div><strong>${run.turns}</strong><span>Turns played</span></div></div>${run.captureResult?.caught?`<div class="capture-reward rarity-${run.captureResult.rarity}">${beastImage(run.captureResult)}<strong>${RARITIES[run.captureResult.rarity].name} ${BEASTS[run.captureResult.id].name} captured</strong><p>Saved in your bestiary. Choose your companion between fights.</p>${button('Choose companion','bestiary','quiet')}</div>`:''}${lost||won?button('Return to title','title'):stageComplete?button(`Continue to Stage ${run.stage+1}`,'next-stage','gold'):`${elite?relicEntry(run.eliteReward):''}<p>${itemArt('gold')} +${run.lastCombatGold??(elite?60:30)} gold${elite?' · Relic secured':''} · Choose one card, or skip.${run.trialUpgradePending?' Your free card upgrade comes next.':''}</p><div class="offers">${run.rewards.map(id=>cardOffer(id,'reward')).join('')}</div>${button('Skip reward','advance','quiet')}`}<p class="small muted">Seed ${escape(run.seed)}</p></section></main>`;}
function beastImage(x){return `<img class="bestiary-art rarity-${x.rarity}" src="assets/beasts/${x.id}.webp" alt="${BEASTS[x.id].name}" draggable="false">`;}
function companionStatus(){const c=run.companion,b=run.battle;if(!c)return 'No companion';if(c.id==='syluun'&&b.companionUses>=2)return 'Healing exhausted';if(b.companionCooldown)return `Ready in ${b.companionCooldown} turn${b.companionCooldown===1?'':'s'}`;if(c.id==='syluun'&&run.hp===run.maxHp)return 'Vitality full';return BEASTS[c.id].ability;}
function battleActions(){const c=run.companion,e=run.battle.enemies[run.battle.target];return `<div class="beast-actions">${c?button(`${BEASTS[c.id].name}<small>${companionStatus()}</small>`,'companion-menu','quiet companion-button'):''}${e?.beast?button(`${itemArt('basic')}Capture<small>1 Core + 1 shard</small>`,'capture-menu','quiet capture-button'):''}${!c&&!e?.beast?'<p class="combat-message">Drag cards to play · Tap to inspect</p>':''}</div>`;}
function captureDialog(){const e=run.battle?.enemies[run.battle.target];if(run.phase!=='combat'||!e?.beast)return;openModal(`Capture ${e.name}`,`<p class="eyebrow rarity-${e.rarity}">${RARITIES[e.rarity].name} · ${BEASTS[e.beast].role}</p><p class="capture-help">Weaken to 25% health for the best odds. Each attempt costs 1 Core and a shard. Failure gives the beast +2 attack damage.</p><div class="shard-options">${Object.entries(SHARDS).map(([id,s])=>button(`${itemArt(id,'capture')}<span class="shard-choice-copy"><strong>${s.name}</strong><span>${captureChance(run,id)}% chance · ${run.shards[id]} left</span></span>`,'capture','quiet shard-'+id,`data-shard="${id}" ${run.shards[id]<1||run.core<1?'disabled':''}`)).join('')}</div><p class="small muted">${run.core<1?'You need at least 1 Core. End your turn to regenerate.':'Rarer beasts are harder to catch. No shard guarantees success.'}</p>`);}
function bestiaryView(){const inRun=!['title','select'].includes(bestiaryReturn),canEquip=!inRun||['map','victory','shop','rest','chest','mystery'].includes(run?.phase),active=inRun?run?.companion:bestiary.selected;return `<main class="bestiary-screen route screen"><header class="topbar">${button(icon('back')+'Back','bestiary-back','quiet')}<h1>Beast bestiary</h1><span class="bestiary-count">${bestiary.caught.length} / 12</span></header><section class="bestiary-panel"><div class="bestiary-intro"><div><p class="eyebrow">The bonded wilds</p><p>Wild beasts can appear unexpectedly during an ascent. Each species has Common, Rare and Legendary variants.</p><p class="small muted">Your collection stays on this browser/device. ${canEquip?(inRun?'Choose one companion for this ascent.':'Choose one companion to start your next ascent.'):'Companions can only be changed between battles.'}</p></div><div class="active-companion"><strong>${active?`${RARITIES[active.rarity].name} ${BEASTS[active.id].name}`:'Travelling alone'}</strong>${button('Travel alone','equip-beast','quiet',!canEquip||!active?'disabled':'')}</div></div><div class="bestiary-grid">${Object.entries(BEASTS).map(([id,b])=>{const caught=bestiary.caught.filter(x=>x.id===id),display=active?.id===id?active:caught.at(-1)||{id,rarity:'common'};return `<article class="beast-entry ${caught.length?'bonded':'uncaught'}"><div class="beast-portrait">${beastImage(display)}<span class="beast-role">${b.role}</span></div><div class="beast-details"><p class="eyebrow">${b.title}</p><h2>${b.name}</h2>${(()=>{const p=beastLevelFromXp(bestiary.xp?.[id]||0);return `<div class="beast-level"><strong>Level ${p.level} / 10</strong><span>${p.level>=10?'Mastered':`${p.xpInto} / ${p.xpNeeded} XP`}</span></div>`;})()}<strong>${b.ability} · ${RARITIES[display.rarity].name}</strong><p>${companionDescription(display,beastLevelFromXp(bestiary.xp?.[id]||0).level)}</p><small>${b.cooldown}-turn cooldown · Free to activate</small><div class="beast-variants">${Object.entries(RARITIES).map(([rarity,r])=>{const key=id+':'+rarity,owned=bestiary.caught.some(x=>beastKey(x)===key),seen=bestiary.seen.some(x=>beastKey(x)===key),selected=active&&beastKey(active)===key;return button(`${r.name}<small>${selected?'Selected':owned?'Take with you':seen?'Seen · not caught':'Not caught'}</small>`,'equip-beast',`quiet rarity-${rarity} ${selected?'equipped':''}`,`data-id="${id}" data-rarity="${rarity}" aria-pressed="${!!selected}" ${!owned||!canEquip?'disabled':''}`);}).join('')}</div></div></article>`;}).join('')}</div><p class="bestiary-footnote">Rare variants have stronger abilities; Legendary variants are strongest. All variants use the same species artwork, with a distinct rarity aura.</p></section></main>`;}
function render(){document.body.classList.toggle('reduced-motion',!settings.motion);const views={title,select,story,map,combat,victory:outcome,'stage-complete':outcome,won:outcome,lost:outcome,shop:room,chest:room,mystery:room,rest:room,bestiary:bestiaryView};app.innerHTML=views[screen]();document.title=`Veyrak: Ascension${screen==='combat'?' · Battle':''}`;}
function navigate(next){screen=next;render();window.scrollTo(0,0);if(next==='map')requestAnimationFrame(()=>{const map=$('.branch-scroll'),node=$('.branch-node.available');if(map&&node)map.scrollLeft=Math.max(0,node.offsetLeft-map.clientWidth/2);});}
function openModal(title,content,kind=''){modal.className=kind;modal.innerHTML=`<div class="modal-heading"><h2>${title}</h2>${button('×','close','close','aria-label="Close dialog"')}</div>${content}`;modal.showModal();}
function upgradeChoices(){const groups=new Map();run.deck.forEach((id,index)=>{if(!CARD_UPGRADES[id])return;const item=groups.get(id);if(item)item.count++;else groups.set(id,{id,index,count:1});});return [...groups.values()];}
function upgradeList(mode){if(run.phase!==(mode==='shop'?'shop':'rest'))return;const cost=mode==='shop'?75:0,choices=upgradeChoices();openModal(mode==='shop'?'Merchant Forge':'Upgrade a card',`<p class="upgrade-intro">${mode==='shop'?'Choose one copy to forge for <strong>75 gold</strong>.':'Choose one copy to strengthen for this ascent.'}</p><div class="upgrade-list">${choices.map(x=>`<button class="upgrade-choice" data-action="upgrade-preview" data-mode="${mode}" data-index="${x.index}" ${run.gold<cost?'disabled':''}><span>${escape(CARDS[x.id].name)}${x.count>1?` <small>×${x.count}</small>`:''}</span><b>→ ${escape(CARDS[CARD_UPGRADES[x.id]].name)}</b><small>${escape(CARDS[CARD_UPGRADES[x.id]].text)}</small></button>`).join('')}</div>${run.gold<cost?'<p class="upgrade-note">You need 75 gold to forge a card.</p>':''}${button('Back','close','quiet')}`,'upgrade-dialog');}
function upgradePreview(mode,index){if(run.phase!==(mode==='shop'?'shop':'rest')||!Number.isInteger(index)||index<0||index>=run.deck.length)return;const id=run.deck[index],next=CARD_UPGRADES[id];if(!next)return;const before=CARDS[id],after=CARDS[next],cost=mode==='shop'?75:0;openModal(mode==='shop'?'Confirm forge':'Confirm upgrade',`<p class="upgrade-intro">${mode==='shop'?'<strong>75 gold</strong> · ':''}One copy of ${escape(before.name)} becomes ${escape(after.name)} for this ascent.</p><div class="upgrade-preview"><section><p class="eyebrow">Current</p>${cardArt(id)}<strong>${escape(before.name)}</strong><p>${before.cost} Core · ${escape(before.text)}</p></section><span class="upgrade-arrow" aria-hidden="true">→</span><section class="after"><p class="eyebrow">Upgraded</p>${cardArt(next)}<strong>${escape(after.name)}</strong><p>${after.cost} Core · ${escape(after.text)}</p></section></div><div class="upgrade-dialog-actions">${button(`${mode==='shop'?'Forge for 75 gold':'Upgrade this card'}`,mode==='shop'?'shop-upgrade-confirm':'upgrade-confirm','gold',`data-index="${index}" ${run.gold<cost?'disabled':''}`)}${button('Choose another','upgrade-list','quiet',`data-mode="${mode}"`)}</div>`,'upgrade-dialog');}
function confirmNew(){const seed=$('#seed')?.value.trim()||crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase();const start=()=>{if(run&&!['won','lost'].includes(run.phase))record('abandoned');const level=selected==='kaerun'?kaerunLevelFromXp(progression.kaerunXp).level:selected==='ilyra'?ilyraLevelFromXp(progression.ilyraXp).level:1;const beastLevel=bestiary.selected?beastLevelFromXp(bestiary.xp?.[bestiary.selected.id]||0).level:1;run=createRun(seed,selected,{companion:bestiary.selected,companionLevel:beastLevel,characterLevel:level});save();storyStage=1;storyPage=0;navigate('story');};if(run&&!['won','lost'].includes(run.phase)){openModal('Replace current ascent?',`<p>Your saved run will end. Begin a new ascent with ${HEROES.find(h=>h.id===selected).name}?</p><div class="dialog-actions">${button('Keep current run','close','quiet')}${button('Begin new ascent','confirm-start')}</div>`);pendingStart=start;}else start();}
let pendingStart;
function settingsDialog(){openModal('Settings',`<div class="setting"><div><strong>Sound effects</strong><p>Soft menu and combat sounds.</p></div><button class="toggle" role="switch" aria-checked="${settings.sound}" data-action="sound">${settings.sound?'On':'Off'}</button></div><div class="setting"><div><strong>Animation</strong><p>Movement and combat effects.</p></div><button class="toggle" role="switch" aria-checked="${settings.motion}" data-action="motion">${settings.motion?'On':'Off'}</button></div><p class="small muted">Saves are stored on this device and browser.</p>`);}
function help(){openModal('Your first battle',`<ol class="help"><li>You regenerate <b>${CORE_REGEN} Core</b> each turn. Unused Core carries over, up to <b>${MAX_CORE}</b>. You also draw <b>5 cards</b>.</li><li>Drag attacks onto an enemy, or skills into the arena. Tap to inspect instead. Its top number is its Core cost.</li>${run?.hero==='ilyra'?'<li><b>Arc Bolt</b> and <b>Crystal Guard</b> build Resonance (your current cap is <b>${run?.levelBonuses?.resonanceCap||3}</b>). <b>Core Spark</b> also gives 1 Core. Spend your Resonance on <b>Resonant Strike</b> or <b>Prism Ward</b>; Prism Ward protects your next turn.</li>':'<li><b>Target Breaker</b> applies Mark. <b>Gauntlet Smash</b> hits Marked foes harder. Kaerun’s first attack on a Marked enemy each turn grants <b>3 Block</b>. Mark fades by 1 after each enemy action.</li>'}<li>Read the enemy intention above it, then choose <b>End turn</b>.</li><li>Unused cards are discarded. The discard pile reshuffles when the draw pile empties.</li><li>Block expires at your next turn. Vitality carries throughout the ascent.</li></ol>${button('Ready','close')}`);}
function animate(target,cls){if(!settings.motion)return;const el=$(target);el?.classList.add(cls);}
let suppressClickUntil=0,drag=null;
function dragDestination(x,y,card){const hit=document.elementFromPoint(x,y);const enemy=hit?.closest('.enemy-target');if(enemy)return {target:Number(enemy.dataset.index),el:enemy};if((card.all||card.randomTarget||(!card.damage&&!card.mark))&&hit?.closest('.arena'))return {target:run.battle.target,el:$('.arena')};return null;}
function finishDrag(event,cancel=false){if(!drag)return;const d=drag;drag=null;d.el.classList.remove('drag-source');document.querySelectorAll('.drop-ready').forEach(x=>x.classList.remove('drop-ready'));d.ghost?.remove();if(d.moved){suppressClickUntil=Date.now()+450;if(!cancel&&run?.phase==='combat'){const dest=dragDestination(event.clientX,event.clientY,d.card);if(dest&&d.card.cost<=run.core){selectTarget(run,dest.target);performCombatAction(playCard,d.index);}}}}
app.addEventListener('pointerdown',event=>{const el=event.target.closest('.ability-card');if(!el||feedbackBusy||run?.phase!=='combat'||modal.open||event.button!==0||drag)return;const index=Number(el.dataset.index),card=CARDS[run.battle.hand[index]];drag={el,index,card,x:event.clientX,y:event.clientY,pointer:event.pointerId,moved:false};el.setPointerCapture(event.pointerId);});
app.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.pointer)return;const d=drag;if(!d.moved&&Math.hypot(event.clientX-d.x,event.clientY-d.y)<8)return;event.preventDefault();if(!d.moved){d.moved=true;d.el.classList.add('drag-source');d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.innerHTML=cardArt(run.battle.hand[d.index]);document.body.appendChild(d.ghost);}d.ghost.style.left=event.clientX+'px';d.ghost.style.top=event.clientY+'px';document.querySelectorAll('.drop-ready').forEach(x=>x.classList.remove('drop-ready'));const dest=dragDestination(event.clientX,event.clientY,d.card);if(dest&&d.card.cost<=run.core)dest.el.classList.add('drop-ready');});
app.addEventListener('pointerup',event=>{if(drag&&event.pointerId===drag.pointer)finishDrag(event);});
app.addEventListener('pointercancel',event=>finishDrag(event,true));
app.addEventListener('lostpointercapture',event=>{if(drag)finishDrag(event,true);});
window.addEventListener('blur',()=>{if(drag)finishDrag({},true);});

app.addEventListener('click',handle);modal.addEventListener('click',handle);
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function handle(event){if(feedbackBusy||Date.now()<suppressClickUntil)return;const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;sound();
 switch(a){
 case 'title':modal.close();navigate('title');break;
 case 'select':navigate('select');break;
 case 'story-previous':storyPage=Math.max(0,storyPage-1);render();break;
 case 'story-next':{const pages=storyPages[storyStage]||storyPages[1];if(storyPage<pages.length-1){storyPage++;render();}else navigate('map');break;}
 case 'story-skip':navigate('map');break;
 case 'bestiary':modal.close();syncBestiary();bestiaryReturn=screen;navigate('bestiary');break;
 case 'bestiary-back':navigate(bestiaryReturn);break;
 case 'equip-beast':{const chosen=el.dataset.id?{id:el.dataset.id,rarity:el.dataset.rarity}:null;if(chosen&&!bestiary.caught.some(x=>beastKey(x)===beastKey(chosen)))break;if(!['title','select'].includes(bestiaryReturn)){if(!persistAction(equipCompanion,chosen,bestiary.caught))break;}bestiary.selected=chosen;write(keys.bestiary,JSON.stringify(bestiary));render();break;}
 case 'capture-menu':captureDialog();break;
 case 'capture':{if(persistAction(captureBeast,el.dataset.shard)){modal.close();navigate(run.phase);const c=run.captureResult;notify(c.caught?(c.duplicate?`Duplicate ${RARITIES[c.rarity].name} ${BEASTS[c.id].name} bonded: +${c.duplicateXp} Beast XP!`:`${RARITIES[c.rarity].name} ${BEASTS[c.id].name} captured!`):'It broke free! Shard spent; beast gains +2 attack damage.');}break;}
 case 'companion-menu':{const c=run.companion;if(!c)break;const b=BEASTS[c.id],bl=run.companionLevel||1;openModal(b.ability,`<div class="companion-inspect">${beastImage(c)}<div><p class="eyebrow">${RARITIES[c.rarity].name} ${b.name} · ${b.role}</p><p>${companionDescription(c,bl)}</p><p class="small">Level ${bl} / 10 · ${b.cooldown}-turn cooldown. No Core cost.${c.id==='rhazek'?' Target: '+escape(run.battle.enemies[run.battle.target].name)+'.':''}</p>${button(companionStatus(),'companion-use','gold',companionReady(run)?'':'disabled')}</div></div>`);break;}
 case 'companion-use':modal.close();performCombatAction(useCompanion);break;
 case 'progression':progressionDialog();break;
 case 'hero':if(!HEROES.find(h=>h.id===el.dataset.hero).available){notify('This hero is locked. Progression unlocks arrive in a later stage.');break;} {const seed=$('#seed').value;selected=el.dataset.hero;render();$('#seed').value=seed;break;}
 case 'start':confirmNew();break;
 case 'confirm-start':modal.close();pendingStart?.();pendingStart=null;break;
 case 'continue':navigate(run.phase);break;
 case 'node':if(run?.debugUnlockAll){const n=run.route.find(x=>x.id===el.dataset.id);if(n&&run.phase==='map'&&!run.visited.includes(n.id)){run.current=null;run.visited=run.visited.filter(id=>run.route.find(x=>x.id===id)?.row<n.row);run.index=Math.max(0,n.row-1);save();} }if(persistAction(chooseNode,el.dataset.id))navigate(run.phase);break;
 case 'target':if(persistAction(selectTarget,Number(el.dataset.index)))render();break;
 case 'inspect':{const i=Number(el.dataset.index),id=run.battle.hand[i],c=CARDS[id];openModal(c.name,`<div class="inspect-card">${cardArt(id)}<div><p class="eyebrow">${c.type} · ${c.cost} Core</p><p>${c.text}</p>${c.mark?'<p class="small">Mark lasts across turns, losing 1 after each enemy action. Mark enables Gauntlet Smash’s bonus.</p>':''}<p class="small">Target: ${run.battle.enemies[run.battle.target].name}</p>${button(c.cost>run.core?'Not enough Core':'Play card','play','gold',`data-index="${i}" ${c.cost>run.core?'disabled':''}`)}${button('Back to hand','close','quiet')}</div></div>`);break;}
 case 'reward':if(persistAction(advance,el.dataset.id))navigate(run.phase);break;
 case 'room':if(persistAction(resolveRoom,el.dataset.choice)){modal.close();navigate(run.phase);}break;
 case 'event-exchange':{
  const i=Number(el.dataset.index);if(run.phase!=='mystery'||run.room?.eventId!=='exchange'||!Number.isInteger(i)||!run.deck[i])break;
  openModal('Confirm Memory Exchange','<p>Trade one copy of <strong>'+escape(CARDS[run.deck[i]].name)+'</strong> for your choice below. No gold cost.</p><div class="offers">'+run.room.cards.map(id=>cardOffer(id,'room','data-choice="exchange:'+i+':'+id+'"')).join('')+'</div>'+button('Back','close','quiet'));break;
 }
 case 'upgrade-list':upgradeList(el.dataset.mode||'rest');break;
 case 'upgrade-preview':upgradePreview(el.dataset.mode||'rest',Number(el.dataset.index));break;
 case 'upgrade-confirm':{const i=Number(el.dataset.index),next=CARD_UPGRADES[run.deck[i]];if(persistAction(upgradeCard,i)){modal.close();navigate(run.phase);notify(`${CARDS[next].name} upgraded for this ascent.`);}break;}
 case 'shop-upgrade-list':upgradeList('shop');break;
 case 'shop-upgrade-confirm':{const i=Number(el.dataset.index),next=CARD_UPGRADES[run.deck[i]];if(persistAction(shopUpgradeCard,i)){modal.close();render();notify(`${CARDS[next].name} forged for 75 gold.`);}break;}
 case 'buy':if(persistAction(buy,Number(el.dataset.index)))render();break;
 case 'sell':if(persistAction(sell,el.dataset.kind,Number(el.dataset.index)))render();break;
 case 'potion':if(run?.phase==='combat')performCombatAction(usePotion);else if(persistAction(usePotion)){render();notify(`Recovered up to ${run.relics.includes('moonchalice')?28:20} Vitality.`);}break;
 case 'enter':if(persistAction(enterBattle)){navigate('combat');if(run.turns===1&&!history.length)help();}break;
 case 'play':modal.close();performCombatAction(playCard,Number(el.dataset.index));break;
 case 'end':performCombatAction(endTurn);break;
 case 'advance':if(persistAction(advance))navigate('map');break;
 case 'next-stage':if(persistAction(continueStage)){if(run.stage===2){storyStage=2;storyPage=0;navigate('story');}else navigate('map');}break;
 case 'close':modal.close();break;
 case 'settings':settingsDialog();break;
 case 'sound':case 'motion':settings[a]=!settings[a];write(keys.settings,JSON.stringify(settings));modal.close();render();settingsDialog();break;
 case 'help':help();break;
 case 'debug-levels':run.debugUnlockAll=!run.debugUnlockAll;save();modal.close();navigate(run.phase);notify(run.debugUnlockAll?'Testing mode enabled. Open Menu to jump stages.':'Testing mode disabled.');break;
 case 'debug-next-stage':if(run?.debugUnlockAll&&run.stage<10){run.phase='stage-complete';run.battle=null;run.room=null;run.current=null;run.block=0;run.core=0;if(persistAction(continueStage)){modal.close();if(run.stage===2){storyStage=2;storyPage=0;navigate('story');}else navigate('map');notify('Testing mode: jumped to Stage '+run.stage+'.');}}break;
 case 'pause':save();openModal('Ascent paused',`<p>${storageError?'Saving is unavailable. Keep this tab open.':`Run saved · Stage ${run.stage||1}, Level ${Math.min(10,(run.index??0)+1)}. You can return to the title and continue this ascent later.`}</p><p class="small muted">Your active run is autosaved as you play. If you die, the ascent ends and this save cannot be resumed.</p><div class="pause-actions">${button('Resume','close')}${button('Save & return to title','title')}${button('View cards','cards','quiet')}${button('View relics','relics','quiet')}${button('Bestiary','bestiary','quiet')}${button('How to play','help','quiet')}${button(run.debugUnlockAll?'Lock test levels':'Unlock all levels','debug-levels','gold')}${run.debugUnlockAll&&run.stage<10?`<div class="debug-stage-jump"><strong>TESTING MODE</strong>${button('NEXT STAGE → '+(run.stage+1),'debug-next-stage','gold')}</div>`:''}${button('Return to title','title','quiet')}</div>`);break;
 case 'relics':openModal('Your relics',`<p>Relics last for this ascent.</p><div class="relic-list">${run.relics.map(id=>relicEntry(id)).join('')||'<p class="muted">Find relics in treasure rooms or buy them from merchants.</p>'}</div>`);break;
 case 'cards':{const counts=[...new Set(run.deck)].map(id=>({id,n:run.deck.filter(x=>x===id).length}));openModal('Your deck',`<p>${run.deck.length} cards · New cards are earned during this ascent.</p><div class="collection-grid">${counts.map(x=>`<article class="collection-card">${cardArt(x.id)}<div><strong>${CARDS[x.id].name} ×${x.n}</strong><span>${CARDS[x.id].cost} Core · ${CARDS[x.id].text}</span></div></article>`).join('')}</div>`);break;
 }
 case 'archive':openModal('Ascent archive',history.length?`<p class="muted">Your last ${history.length} ascents on this device.</p><div class="archive-list">${history.map(r=>`<article><div><strong>${HEROES.find(h=>h.id===r.hero).name}</strong><span>${r.outcome==='won'?'Summit reached':r.outcome==='lost'?'Fallen':'Abandoned'} · ${r.turns} turns</span></div><code>${escape(r.seed)}</code></article>`).join('')}</div>`:'<div class="empty-archive">'+icon('core')+'<p>Your story begins with your first ascent.</p><p class="small muted">Completed runs and their seeds will appear here.</p></div>');break;
 case 'draw':case 'discard':{const pile=run.battle[a];const counts=Object.keys(CARDS).map(id=>({id,n:pile.filter(c=>c===id).length})).filter(x=>x.n);openModal(a==='draw'?'Draw pile':'Discard pile',`<p class="muted">${a==='draw'?'Card counts only — draw order stays hidden.':'Cards return to the draw pile when it empties.'}</p><ul class="pile-list">${counts.map(x=>`<li>${CARDS[x.id].name}<strong>× ${x.n}</strong></li>`).join('')||'<li>Empty</li>'}</ul>`);break;}
 }
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open&&['combat','map'].includes(screen)){e.preventDefault();openModal('Ascent paused',`<div class="pause-actions">${button('Resume','close')}${button('Return to title','title','quiet')}</div>`);}});
window.addEventListener('pagehide',save);
syncBestiary();render();if(storageError)notify('Saving is unavailable in this browser. Your current run will work in this tab.');
for(const src of ['council-background','kaerun','ilyra','approved-selection']){const i=new Image();i.src=`assets/${src}.png`;}

