.mastery-levels{display:grid;gap:6px}.mastery-level{display:grid;grid-template-columns:38px 1fr auto;gap:10px;align-items:center;padding:9px 11px;border:1px solid #58647755;background:#0d1522}.mastery-level>b{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;border:1px solid #66758a;color:#c8d0db}.mastery-level strong{font-size:11px;color:#d7dde6}.mastery-level p{margin:3px 0 0;font-size:11px;color:#aeb8c6}.mastery-level>span{font-size:8px;letter-spacing:.1em;color:#718095}.mastery-level.unlocked{border-color:#8e784e66}.mastery-level.unlocked>b{border-color:#b99b61;color:#e9cb8c}.mastery-level.current{border-color:#e0b96f;background:#1b1a1b;box-shadow:inset 0 0 20px #c8993420}.mastery-level.current>b{background:#b58a45;color:#07101b;border-color:#f1d08b}.mastery-level.current>span{color:#efcb83}.mastery-level.milestone{border-width:2px}.mastery-level.milestone strong{color:#f0c978}
