@media(orientation:landscape) and (max-height:600px){.progression-hint{bottom:5px;padding:4px 8px;font-size:7px}.mastery{max-height:68vh}.mastery-level{padding:6px 9px}.mastery-level>b{width:27px;height:27px}.mastery-level p{font-size:9px}}

/* v32: keep progression prompt above selected hero and make level/XP unambiguous. */
.hero-progression-wrap{position:relative;height:clamp(330px,60vh,600px);display:flex;align-items:flex-end;justify-content:center}
.hero-progression-wrap .hero-display{height:100%;width:100%}
.hero-progression-wrap .progression-hint{top:4px;bottom:auto;left:50%;z-index:6}
.level-readout{display:grid!important;grid-template-columns:max-content 1fr;align-items:baseline;justify-content:center;column-gap:12px;row-gap:4px;margin:12px auto 0;width:max-content;max-width:100%}
.level-readout .character-level{display:block;white-space:nowrap;font-size:20px;line-height:1.1}
.level-readout .character-xp{display:block;white-space:nowrap;font-size:13px;line-height:1.1;color:#e5c783}
.level-readout small{grid-column:1/-1;display:block;white-space:normal;text-align:center;font-size:10px;line-height:1.25;color:#bfc7d2}
@media(orientation:landscape) and (max-height:600px){.hero-progression-wrap{height:100%}.hero-progression-wrap .progression-hint{top:2px}.level-readout{margin-top:5px;column-gap:8px}.level-readout .character-level{font-size:16px}.level-readout .character-xp{font-size:10px}.level-readout small{font-size:8px}}

/* v33: restore landscape character-select fit after adding mastery wrapper. */
@media(orientation:landscape) and (max-height:600px){
 .selection .hero-progression-wrap{height:100%;min-height:0;overflow:hidden;display:flex;align-items:stretch;justify-content:center}
 .selection .hero-progression-wrap .hero-display{height:100%;min-height:0;overflow:hidden;display:flex;align-items:flex-end;justify-content:center}
 .selection .hero-progression-wrap .hero-art{height:100%;max-height:100%;width:100%;object-fit:contain;object-position:center bottom}
 .selection .hero-progression-wrap .progression-hint{top:5px;bottom:auto}
 .selection .dossier{display:grid!important;visibility:visible!important;opacity:1!important;grid-template-columns:1fr 1fr;grid-template-rows:auto auto auto auto auto;align-content:center}
 .selection .level-readout{grid-column:1/-1;display:grid!important;width:100%;grid-template-columns:max-content max-content;justify-content:center;margin:1px 0 2px;column-gap:8px;row-gap:1px}
 .selection .level-readout .character-level{font-size:14px}
 .selection .level-readout .character-xp{font-size:9px}
 .selection .level-readout small{grid-column:1/-1;font-size:7px;line-height:1.1}
 .selection .traits{grid-column:1/-1;grid-row:auto;justify-content:center}
 .selection #seed{grid-column:1/-1}
 .selection .dossier>.gold{grid-column:1/-1}
 .selection .dossier>.companion-select{grid-column:1/-1;display:block!important}
}

/* v34: level, XP and current perk are deliberately separate lines. */
.level-readout,
.selection .level-readout{display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:3px!important;width:100%!important;max-width:100%!important;margin:12px auto 8px!important;text-align:center!important}
.level-readout .character-level,
.selection .level-readout .character-level{display:block!important;width:100%;font-size:clamp(26px,3vw,36px)!important;line-height:1!important;letter-spacing:.06em;white-space:nowrap;color:#f6e8c9}
.level-readout .character-xp,
.selection .level-readout .character-xp{display:block!important;width:100%;font-size:14px!important;line-height:1.25!important;white-space:nowrap;color:#e5c783}
.level-readout .character-perk,
.selection .level-readout .character-perk{display:block!important;width:100%;font-size:10px!important;line-height:1.25!important;white-space:normal!important;color:#aeb8c6}
@media(orientation:landscape) and (max-height:600px){
 .selection .level-readout{grid-column:1/-1!important;display:flex!important;margin:2px 0 3px!important;gap:1px!important}
 .selection .level-readout .character-level{font-size:22px!important}
 .selection .level-readout .character-xp{font-size:10px!important}
 .selection .level-readout .character-perk{font-size:8px!important}
}

/* v35: reserve a dedicated strip above hero artwork for the progression prompt. */
@media(orientation:landscape) and (max-height:600px){
 .selection .hero-progression-wrap{display:grid!important;grid-template-rows:28px minmax(0,1fr)!important;align-items:stretch!important;overflow:hidden}
 .selection .hero-progression-wrap .progression-hint{position:static!important;transform:none!important;justify-self:center;align-self:center;margin:0!important}
