/* v37: progression label is an actual control; mastery explains hero playstyle. */
.progression-open{appearance:none;-webkit-appearance:none;cursor:pointer}
.hero-progression-wrap .progression-open{pointer-events:auto!important}
.mastery-playstyle{margin:2px 0 18px;padding:12px 14px;border:1px solid #9d83566b;background:#111a28;text-align:left}
.mastery-playstyle>span{display:block;margin-bottom:6px;font-size:9px;font-weight:700;letter-spacing:.18em;color:#e5c783}
