.mastery{width:min(920px,90vw)!important;max-width:100%;overflow-x:hidden!important;overflow-y:auto}
.mastery-playstyle,.mastery-playstyle p,.mastery-level,.mastery-level p{max-width:100%;min-width:0;white-space:normal!important;overflow-wrap:anywhere;word-break:normal}
