/* v53: merchant card forge */
.merchant-forge{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin:14px auto 18px;padding:10px 14px;max-width:720px;border:1px solid #b9904f80;background:#161107cc;border-radius:8px}
