.beast-level{display:flex;align-items:center;gap:8px;margin:5px 0 7px}.beast-level strong{color:#e8c77f}.beast-level span{font-size:9px;color:#aeb9bd;border:1px solid #ffffff20;border-radius:999px;padding:2px 7px}

