.upgrade-card-cost,.upgrade-card-name,.upgrade-card-effect{position:absolute;z-index:3;display:flex;align-items:center;justify-content:center;text-align:center;color:#fff0c9;text-shadow:0 1px 3px #000;font-family:Georgia,serif}
