/* One comparison flow for the Sanctuary and the merchant. */
dialog.upgrade-dialog{width:min(760px,94vw);max-height:min(90svh,860px);overflow-y:auto}
.upgrade-dialog .upgrade-intro{font-size:13px;line-height:1.5;color:#cfdae5;margin-bottom:14px}
.upgrade-dialog .upgrade-intro strong{color:#f2ce81}
.upgrade-dialog .upgrade-list{max-height:min(60svh,560px);grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:12px}
.upgrade-dialog .upgrade-choice{min-width:0;min-height:75px;padding:11px 13px}
.upgrade-dialog .upgrade-choice>span,.upgrade-dialog .upgrade-choice>b{min-width:0;overflow-wrap:anywhere}
.upgrade-dialog .upgrade-choice>span small{font:11px Inter,system-ui,sans-serif;color:#d8b96f}
.upgrade-dialog .upgrade-choice:disabled{opacity:.5}
.upgrade-dialog .upgrade-note{color:#efb7a6;font-size:12px;margin:4px 0 12px}
.upgrade-dialog .upgrade-preview{gap:18px;margin:8px 0 16px;grid-template-columns:minmax(0,1fr) 40px minmax(0,1fr)}
.upgrade-dialog .upgrade-preview section{min-width:0}.upgrade-dialog .upgrade-preview section>.eyebrow{margin-bottom:12px}
.upgrade-dialog .upgrade-preview .sheet-card,.upgrade-dialog .upgrade-preview .ilyra-card,.upgrade-dialog .upgrade-preview .tech-card,.upgrade-dialog .upgrade-preview .neutral-card,.upgrade-dialog .upgrade-preview .upgraded-card-art{width:min(170px,100%);height:auto!important;aspect-ratio:307/490}
.upgrade-dialog .upgrade-preview section>strong{font-size:16px}.upgrade-dialog .upgrade-preview section>p:last-child{font-size:12px;line-height:1.45;min-height:42px;margin-top:5px}
.upgrade-dialog-actions{display:flex;justify-content:center;align-items:center;gap:12px;flex-wrap:wrap}
.upgrade-dialog-actions .gold{min-width:min(290px,100%)}
@media(max-width:600px){dialog.upgrade-dialog{width:95vw;padding:15px;max-height:90dvh}.upgrade-dialog .modal-heading{margin-bottom:12px;padding-bottom:10px}.upgrade-dialog .modal-heading h2{font-size:19px}.upgrade-dialog .upgrade-list{grid-template-columns:1fr;max-height:57dvh}.upgrade-dialog .upgrade-choice{min-height:62px}.upgrade-dialog .upgrade-preview{grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr);gap:5px}.upgrade-dialog .upgrade-preview .sheet-card,.upgrade-dialog .upgrade-preview .ilyra-card,.upgrade-dialog .upgrade-preview .tech-card,.upgrade-dialog .upgrade-preview .neutral-card,.upgrade-dialog .upgrade-preview .upgraded-card-art{width:min(125px,100%)}.upgrade-dialog .upgrade-preview section>p:last-child{font-size:10px}.upgrade-dialog-actions .gold{width:100%;min-width:0}}
@media(orientation:landscape) and (max-height:550px){dialog.upgrade-dialog{width:min(820px,95vw);max-height:92dvh;padding:14px}.upgrade-dialog .upgrade-preview .sheet-card,.upgrade-dialog .upgrade-preview .ilyra-card,.upgrade-dialog .upgrade-preview .tech-card,.upgrade-dialog .upgrade-preview .neutral-card,.upgrade-dialog .upgrade-preview .upgraded-card-art{width:min(100px,100%)}.upgrade-dialog .upgrade-preview section>.eyebrow{margin-bottom:4px}.upgrade-dialog .upgrade-preview section>p:last-child{min-height:0}.upgrade-dialog .upgrade-list{max-height:48dvh}}

/* Crystal and lava cavern arena for every Stage 2 encounter. */
.battle.stage-2{background-image:linear-gradient(rgba(3,8,16,.18),rgba(2,6,13,.34)),url('assets/stage2-cavern.jpg')}

/* Preserve raster boss proportions at every viewport size. */
.battle .enemy-target img.boss-art{width:100%;height:72%;max-width:100%;max-height:72%;object-fit:contain;object-position:center bottom;flex-shrink:0}


/* Overlay effects never intercept a card drag or change fighter proportions. */
.combat-fx-layer{position:fixed;inset:0;z-index:900;pointer-events:none;overflow:hidden;contain:layout paint}
.combat-resolving .hand,.combat-resolving .combat-toolbar,.combat-resolving .enemy-group,.combat-resolving .run-top,.combat-resolving .pile-row{pointer-events:none}
.combat-resolving .enemy-art,.combat-resolving .combat-hero{will-change:translate,filter}
.combat-fx-number{position:absolute;translate:-50% -50%;font:800 clamp(17px,2.1vw,30px)/1.1 Inter,system-ui,sans-serif;white-space:nowrap;text-shadow:0 2px 3px #000,0 0 9px #000,1px 0 #000,-1px 0 #000;animation:combat-number .55s ease-out both}
.combat-fx-number.damage{color:#ffe2ba}.combat-fx-number.blocked{color:#abe7ff;font-size:clamp(12px,1.3vw,19px)}
.combat-fx-number.guard{color:#a6ddff;font-size:clamp(13px,1.4vw,21px)}.combat-fx-number.heal{color:#9af5c9;font-size:clamp(13px,1.4vw,21px)}
.combat-fx-number.status{color:#e2c4ff;font-size:clamp(11px,1.2vw,17px)}.combat-fx-number.block-break{color:#ffcf79;font-size:clamp(10px,1vw,15px);letter-spacing:.06em}
.combat-fx-trail{position:absolute;height:5px;transform-origin:left center;border-radius:50%;opacity:0;animation:combat-trail .22s ease-out both}
.gauntlet-swipe{background:linear-gradient(90deg,transparent,#d3a35c88,#fff2c6);box-shadow:0 0 12px #efb057;clip-path:polygon(0 45%,85% 0,100% 50%,85% 100%,0 55%)}
.crystal-bolt{height:4px;background:linear-gradient(90deg,transparent,#ba8aff,#fff0ff);box-shadow:0 0 11px #a672ff,0 0 22px #8662c8}
.combat-fx-impact{position:absolute;width:70px;height:70px;border:3px solid #fff0b3;border-radius:50%;translate:-50% -50%;box-shadow:0 0 15px #e6ab50,inset 0 0 12px #e6ab50;animation:combat-impact .23s ease-out both}
.crystal-impact{border-color:#ead5ff;box-shadow:0 0 20px #b087ff,inset 0 0 14px #ae76ff}
.combat-fx-still .combat-fx-number{animation:none!important}.combat-fx-still .combat-fx-trail,.combat-fx-still .combat-fx-impact{display:none}
@keyframes combat-number{0%{opacity:0;transform:translateY(5px) scale(.85)}18%{opacity:1;transform:translateY(-2px) scale(1.06)}65%{opacity:1}100%{opacity:0;transform:translateY(-38px) scale(1)}}
@keyframes combat-trail{0%{opacity:0;scale:.12 1}40%{opacity:.95;scale:1 1}100%{opacity:0;scale:1 1}}
@keyframes combat-impact{0%{opacity:.9;scale:.35}100%{opacity:0;scale:1.3}}
@media(prefers-reduced-motion:reduce){.combat-fx-number{animation:none}.combat-fx-trail,.combat-fx-impact{display:none}}

/* Mystery choices reuse the card and upgrade layouts in both orientations. */
.event-technique{padding:1rem;border:1px solid #b9975955;border-radius:12px;background:#111722;margin:.5rem 0}
.event-technique p{line-height:1.5}
.room-panel .dialog-actions{flex-wrap:wrap;gap:.6rem}
.room-panel .offers{max-width:100%}
.room-panel .offers .collection-card{min-width:0}

/* Illustrated items retain their proportions at every display size. */
.item-art{display:inline-block;width:28px;height:28px;object-fit:contain;vertical-align:middle;flex-shrink:0;pointer-events:none;user-select:none;-webkit-user-drag:none;background:transparent}
.item-count{display:inline-flex;align-items:center;gap:4px}
.shard-counts{display:inline-flex;align-items:center;gap:8px}
.inventory-bar .item-art{width:24px;height:24px}
.item-shop{display:block;width:110px;height:145px;margin:0 auto}
.item-chest{display:block;width:210px;height:160px;margin:8px auto}
.item-capture{width:60px;height:66px;align-self:center}
.shard-choice-copy{display:grid;gap:6px}
.item-map{width:30px;height:30px;display:block}
.branch-node b:has(.item-map){height:30px;display:grid;place-items:center}
.run-location .item-art{width:18px;height:18px}
.result-panel>p .item-art{width:24px;height:24px}
.capture-button>.item-art{width:22px;height:22px}
.shard-options button{align-items:center}
.room-panel .dialog-actions .item-art{margin-right:5px}
@media(orientation:landscape) and (max-height:600px){
 .item-chest{width:145px;height:100px}
 .item-shop{width:86px;height:105px}
 .item-capture{width:42px;height:46px}
}
@media(max-width:600px){
 .inventory-bar{gap:8px}
 .shard-counts{gap:6px}
 .shard-options .shard-choice-copy{text-align:left;flex:1}
 .shard-options .item-capture{width:42px;height:46px}
}
